import './service.css';

export const metadata = { title: "Transcranial Magnetic Stimulation (TMS) | The Center for Child and Family Psychiatry, PC" };

const content = "\n\n\n\n<section class=\"page-head head-split head-big\">\n<div class=\"hero-blob\"></div>\n<div class=\"section-inner\">\n<div class=\"head-grid\">\n<div class=\"head-img\"><picture><source media=\"(max-width:860px)\" srcset=\"data:image/jpeg;base64,\"/><img alt=\"NeuroStar TMS treatment room with treatment chair\" class=\"head-photo\" src=\"/services-assets/01e27ba1b523dabfc7.jpg\"/></picture><img alt=\"NeuroStar Advanced Therapy for Mental Health\" class=\"ns-logo\" src=\"/services-assets/83e35ff59dc659fb79.png\"/></div>\n<div class=\"head-text\">\n<div class=\"crumbs\"><a href=\"/services\">Services</a> / Transcranial Magnetic Stimulation (TMS)</div>\n<span class=\"eyebrow\">Our services</span>\n<h1 style=\"color:var(--purple);\">Transcranial Magnetic Stimulation (TMS)</h1>\n<p class=\"sub-line\">An alternative to medication for depression and OCD</p>\n<p>If medication has not given you the relief you hoped for, there is another way. NeuroStar TMS treats depression at the source, with no medication and no surgery.</p>\n<div class=\"cta-row\">\n<a class=\"btn btn-solid btn-purple\" href=\"https://consumer.scheduling.athena.io?locationId=27185-1\">Book Now</a>\n</div>\n</div>\n</div>\n<p class=\"age-note\" style=\"color:#5E3F7A;\">Approved for depression treatment in ages 15 and up and OCD treatment in ages 22 and up</p>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div>\n<div style=\"max-width:720px;margin:28px auto;padding:0 20px;\"><img alt=\"A patient smiling beside a clinician during NeuroStar TMS treatment\" src=\"/services-assets/19a2f63abebb2684f0.jpg\" style=\"display:block;width:100%;height:auto;border-radius:16px;box-shadow:var(--shadow);\"/></div>\n<section>\n<div class=\"section-inner panel\" style=\"--accent:var(--purple);\">\n<span class=\"eyebrow\">TMS vs. medication</span>\n<h2 class=\"sec-h\">Why Choose TMS?</h2>\n<ul class=\"why-list\">\n<li><b>Goes straight to your brain.</b> Unlike medications, which must travel through your entire body (including your stomach, heart, and liver) to reach the brain, TMS delivers magnetic pulses directly to the part of the brain that regulates mood.</li>\n<li><b>Fewer side effects.</b> Medications can cause weight gain, sexual dysfunction, emotional numbing, nausea, insomnia, and fatigue. TMS typically causes only mild, temporary scalp discomfort or a light headache.</li>\n<li><b>No pills and a clear finish line.</b> There are no pills to take. Treatment begins with one session a day and gradually tapers in frequency. After about 8 weeks, treatment is complete!</li>\n<li><b>Zero downtime.</b> TMS causes no drowsiness or cognitive fog, so you can drive yourself to and from appointments and return to school or work immediately.</li>\n</ul>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div>\n<section>\n<div class=\"section-inner panel\" style=\"--accent:var(--purple);\">\n<span class=\"eyebrow\">About this service</span>\n<h2 class=\"sec-h\">What to know</h2>\n<div class=\"about-wrap\"><div class=\"tw-block\"><img alt=\"NeuroStar TMS therapy system with treatment chair\" class=\"tw-r tw-plain\" src=\"/services-assets/c336958465f58a564a.jpg\"/><p class=\"about-p\">Transcranial Magnetic Stimulation (TMS) uses gentle, targeted magnetic pulses to stimulate areas of the brain linked to mood. NeuroStar TMS is an FDA-cleared, non-invasive treatment for depression and obsessive-compulsive disorder (OCD), and a well-established option when antidepressants have not provided enough relief.</p><p class=\"about-p\">Sessions take place in our office while you sit comfortably in a treatment chair. There is no anesthesia, no sedation, and no recovery time, so most patients return to their normal day right after. We are proud to offer TMS to teens and adults ages 15 and up.</p></div><div class=\"tw-block\"><p class=\"about-p\">Your treatment is guided by a team trained in NeuroStar TMS. Before your first session, your provider reviews your history, maps the right area of the brain for your treatment, and walks you through each step, so you always know what to expect.</p></div><div class=\"tw-block\"><p class=\"about-p\">Sessions are short and simple. You relax in the chair while the NeuroStar device delivers gentle pulses, then you carry on with your day. Many patients listen to music or simply rest during treatment.</p></div><div class=\"tw-block\"><img alt=\"A session lasts as little as 19 minutes per day. Resume normal activities immediately after treatment. 36 treatment sessions to completion.\" class=\"tw-l tw-plain tw-stats\" src=\"/services-assets/25e12a697c9e5cf7a0.png\"/><p class=\"about-p\">A full course of NeuroStar TMS is 36 treatment sessions, given over several weeks. Your provider will explain the schedule and track your progress along the way.</p></div></div>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div>\n<section>\n<div class=\"section-inner\">\n<div class=\"section-head centered\" style=\"margin-bottom:22px;\"><h2 style=\"color:var(--teal-deep); font-size:clamp(22px,2.6vw,30px);\">Learn more about TMS on the NeuroStar website</h2></div>\n<div class=\"cta-inline\" style=\"justify-content:center; gap:14px; flex-wrap:wrap; margin:0;\"><a class=\"btn btn-solid btn-purple\" href=\"https://neurostar.com/what-is-neurostar-advanced-therapy/\" rel=\"noopener\" target=\"_blank\">About TMS</a><a class=\"btn btn-solid btn-purple\" href=\"https://neurostar.com/blog/can-adolescents-receive-neurostar-tms-treatments/\" rel=\"noopener\" target=\"_blank\">About TMS for Adolescents</a></div>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div>\n<section>\n<div class=\"section-inner\" style=\"--accent:var(--purple);\">\n<div class=\"section-head centered\"><span class=\"eyebrow\">Why patients choose us</span><h2 style=\"color:var(--teal-deep)\">What You Can Expect From Us</h2></div>\n<div class=\"ben-grid\"><div class=\"ben\"><h3>Medication-free</h3><p>No daily pills and none of the side effects that come with them.</p></div><div class=\"ben\"><h3>Little to no downtime</h3><p>Drive yourself to and from sessions and carry on with your day.</p></div><div class=\"ben\"><h3>Local, expert care</h3><p>Treatment right here in Killeen from a team trained in NeuroStar.</p></div></div>\n<div style=\"max-width:440px;margin:28px auto 0;padding:0 20px;\"><img alt=\"Clinicians reviewing a NeuroStar training guide beside the TMS device\" src=\"/services-assets/1987c1a8a7cb3fff6c.jpg\" style=\"display:block;width:100%;height:auto;border-radius:16px;box-shadow:var(--shadow);\"/></div>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div>\n<section>\n<div class=\"section-inner\" style=\"--accent:var(--purple);\">\n<div class=\"ad-band\">\n<div class=\"ad-text\">\n<span class=\"eyebrow\">Treatment without the downtime</span>\n<h2 style=\"color:var(--teal-deep)\">Drive in. Drive out. Get on with your life.</h2>\n<p>TMS requires no sedation and no medication, so you can drive yourself to and from every session and return to work, school, or family right afterward.</p>\n<div class=\"cta-row\"><a class=\"btn btn-solid btn-purple\" href=\"https://consumer.scheduling.athena.io?locationId=27185-1\">Book Now</a></div>\n</div>\n<img alt=\"NeuroStar TMS system. No sedation. No drugs. Drive in, drive out, and get on with your life.\" src=\"/services-assets/e7a3998067c44d5d31.jpg\"/>\n</div>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div><section>\n<div class=\"section-inner panel\" style=\"--accent:var(--purple);\">\n<div class=\"section-head centered\"><span class=\"eyebrow\">What to expect</span><h2 style=\"color:var(--teal-deep)\">Your TMS Treatment Schedule</h2><p>The schedule is structured and calls for a daily commitment, but each session itself is short.</p></div>\n<div class=\"table-wrap\">\n<table class=\"sched\">\n<thead><tr><th>Phase</th><th>Timing</th><th>What Happens</th></tr></thead>\n<tbody>\n<tr><td><span class=\"ph\">1</span> <strong>Daily Treatment</strong></td><td>Weeks 1 to 6</td><td>One session a day, 5 days a week (Monday through Friday), for 30 treatments in total.</td></tr>\n<tr><td><span class=\"ph\">2</span> <strong>Taper</strong></td><td>Final 2 weeks</td><td>Sessions are gradually reduced to 2 or 3 times a week for a final 6 treatments, easing you off therapy.</td></tr>\n<tr><td><span class=\"ph\">✓</span> <strong>Full Course</strong></td><td>About 8 weeks</td><td>A standard course is 36 sessions in total.</td></tr>\n</tbody>\n</table>\n</div>\n<div style=\"max-width:440px;margin:38px auto 0;padding:0 20px;\"><img alt=\"A patient smiling while receiving NeuroStar TMS treatment from a clinician\" src=\"/services-assets/25bf3724e27c20f4b2.jpg\" style=\"display:block;width:100%;height:auto;border-radius:16px;box-shadow:var(--shadow);\"/></div>\n<div class=\"section-head centered\" style=\"margin-top:38px;\"><h2 style=\"color:var(--teal-deep); font-size:clamp(22px,2.6vw,30px);\">How Long Is Each Session?</h2><p>Session length depends on the protocol your doctor prescribes.</p></div>\n<div class=\"table-wrap\">\n<table class=\"sched\">\n<thead><tr><th>Protocol</th><th>Length</th><th>Details</th></tr></thead>\n<tbody>\n<tr><td><strong>Standard</strong></td><td>About 37 minutes</td><td>The traditional NeuroStar treatment protocol.</td></tr>\n<tr><td><strong>Dash</strong></td><td>19 minutes</td><td>NeuroStar's newer, advanced settings cut the session time nearly in half.</td></tr>\n<tr><td><strong>Theta Burst (TBS)</strong></td><td>About 3 minutes</td><td>An accelerated protocol that mimics natural brain rhythms and can finish an entire session in just a few minutes. Offered at our clinic, where it is our most common form of treatment.</td></tr>\n</tbody>\n</table>\n</div>\n<div class=\"ben-grid\" style=\"margin-top:28px;\">\n<div class=\"ben\"><h3>Zero downtime</h3><p>There is no required observation period and no driving restriction. You are fully alert the moment the magnetic pulses end.</p></div>\n<div class=\"ben\"><h3>Non-invasive</h3><p>There are no pricks, needles, or medications, and you do not need to change clothes. TMS is a non-invasive procedure that requires little preparation.</p></div>\n<div class=\"ben\"><h3>Awake the whole time</h3><p>No sedation or anesthesia is required, and you stay awake and alert from start to finish, no matter how long your session lasts.</p></div>\n</div>\n<p class=\"note\" style=\"text-align:center;\">Your provider will confirm your exact schedule and protocol based on your evaluation.</p>\n<div class=\"cta-inline\" style=\"justify-content:center;\"><a class=\"btn btn-solid btn-purple\" href=\"https://consumer.scheduling.athena.io?locationId=27185-1\">Book Now</a></div>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div><section>\n<div class=\"section-inner panel\" style=\"--accent:var(--purple);\">\n<span class=\"eyebrow\">How it works</span>\n<h2 class=\"sec-h\">Treat Depression at the Source</h2>\n<div class=\"tw-block\"><figure class=\"pet-fig\"><img alt=\"PET scans of an adult depressed brain and a non-depressed brain, showing lower activity in the depressed brain\" src=\"/services-assets/9de268986126e7e912.jpg\"/></figure>\n<p class=\"about-p\">More than 280 million people around the world struggle with depression.<sup><a href=\"#ref1\">1</a></sup> Depression is a disorder caused by decreased activity in areas of the brain involved in regulating mood.</p>\n<p class=\"about-p\">NeuroStar TMS goes right to the source of depression, your brain. It is a non-invasive, non-drug treatment that uses focused magnetic pulses to \"wake up\" those areas and help your brain work the way it should.<sup><a href=\"#ref2\">2</a>, <a href=\"#ref3\">3</a></sup> It is like physical therapy for your brain.</p>\n<p class=\"about-p\">The scans show the difference: the brain on the left, with depression, is far less active than the non-depressed brain on the right.</p>\n</div>\n<div class=\"stat-row\">\n<div class=\"stat\"><b>280 million+</b><span>people worldwide struggle with depression<sup><a href=\"#ref1\">1</a></sup></span></div>\n<div class=\"stat\"><b>300 million+</b><span>people in the U.S. have insurance that covers NeuroStar<sup><a href=\"#ref4\">4</a></sup></span></div>\n</div>\n<p class=\"about-p\" style=\"margin-top:22px;\">Most major insurance companies cover NeuroStar TMS. Our team will help you find out if your insurance covers it. Financing options may be available for patients whose treatment is not covered by insurance.</p>\n<p class=\"about-p\" style=\"margin-top:22px;\">Many people living with depression have already tried antidepressants without getting enough relief. Others want a treatment that suits their own needs or those of someone they love. Either way, medication is not the only path to feeling better.</p>\n<p class=\"about-p\">More than 13,000 adolescents have received NeuroStar TMS, across more than 400,000 treatment sessions. (Data on File, 2026)</p>\n<div style=\"max-width:520px;margin:24px auto 0;\"><img alt=\"Proven results in adolescents: 78 percent improvement in depression symptoms and 48 percent symptom relief (remission)\" src=\"/services-assets/48ee1ffc03ab3f1b8f.jpg\" style=\"display:block;width:100%;height:auto;border-radius:16px;box-shadow:var(--shadow);\"/><p class=\"note\" style=\"text-align:center;margin-top:10px;\">Results in patients ages 12 to 21.<sup><a href=\"#ref5\">5</a></sup></p></div>\n<h2 class=\"sec-h\" style=\"margin-top:44px;\">New Frontiers in Medicine</h2>\n<p class=\"about-p\">TMS is a new technology that is breaking barriers in medicine, and its uses have grown steadily since the FDA first cleared it in 2008.</p>\n<p class=\"about-p\" style=\"margin-bottom:6px;\"><b>Cleared by the FDA for:</b></p>\n<ul class=\"detail-list\">\n<li>Depression: adults 22 and up who have not improved with medication</li>\n<li>Depression: adolescents 15 to 21, as an add-on treatment</li>\n<li>Anxious depression: adults, 22 and up</li>\n<li>OCD: adults, 22 and up</li>\n<li>Migraine and smoking cessation (not offered at our clinic at this time)</li>\n</ul>\n<p class=\"about-p\" style=\"margin-bottom:6px;margin-top:18px;\"><b>TMS is only getting started. Research is underway for the conditions below, but the FDA has not yet approved TMS for them:</b></p>\n<ul class=\"detail-list\">\n<li>Anxiety disorders, PTSD, and bipolar disorder</li>\n<li>Chronic pain</li>\n<li>Stroke and paralysis rehabilitation</li>\n<li>Alzheimer's disease, Parkinson's disease, and mild cognitive impairment</li>\n</ul>\n<p class=\"about-p\" style=\"margin-top:18px;\">We look forward to offering TMS for more conditions as the research advances. TMS offers new hope, and we are proud to be part of this movement.</p>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div>\n<section>\n<div class=\"section-inner panel\" style=\"--accent:var(--purple);\">\n<div class=\"detail-grid\">\n<div class=\"detail-col\">\n<span class=\"eyebrow\">Who it may help</span>\n<h2>Is this right for you?</h2>\n<ul class=\"detail-list\"><li>Depression that has not improved with medication</li><li>Wanting to avoid medication side effects</li><li>Obsessive-compulsive disorder (OCD)</li><li>Teens and adults ages 15 and up</li></ul>\n</div>\n<div class=\"detail-col\">\n<span class=\"eyebrow\">What to expect</span>\n<h2>Your care</h2>\n<ul class=\"detail-list\"><li>An evaluation to confirm TMS is right for you</li><li>A personalized treatment plan</li><li>Short, comfortable in-office sessions</li><li>Help with insurance prior authorization from our team</li></ul>\n</div>\n</div>\n<div class=\"cta-inline\">\n<a class=\"btn btn-solid btn-purple\" href=\"https://consumer.scheduling.athena.io?locationId=27185-1\">Book an Appointment</a>\n</div>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--purple)\"></span><span class=\"line\"></span></div>\n<section>\n<div class=\"section-inner panel\" style=\"--accent:var(--purple);\">\n<div class=\"section-head centered\"><span class=\"eyebrow\">Common questions</span><h2 style=\"color:var(--teal-deep)\">Frequently Asked Questions</h2></div>\n<div class=\"faq-wrap\"><details class=\"faq\"><summary>Why should I use TMS instead of medications?</summary><p>TMS targets the mood-regulating area of the brain directly (the prefrontal cortex), while medication travels through your whole bloodstream and can affect organs like the stomach, heart, and liver. Common medication side effects include weight gain, sexual dysfunction, emotional numbing, nausea, insomnia, and fatigue. With TMS, side effects are usually limited to mild, temporary scalp discomfort or a light headache. Medication is a pill taken every day, often indefinitely, while TMS is a structured course of daily treatments with no long-term daily maintenance required for most patients. There is also no downtime: you can drive yourself to and from appointments and return to school or work immediately.</p></details><details class=\"faq\"><summary>Does TMS hurt?</summary><p>Most patients describe a tapping sensation on the scalp. Your care team will adjust the treatment for your comfort.</p></details><details class=\"faq\"><summary>How long does each session last?</summary><p>The exact timing depends on the machine and treatment protocol your doctor prescribes. The standard protocol takes about 37 minutes per session. NeuroStar's newer Dash protocol can cut that to 19 minutes. Our clinic also offers an accelerated Theta Burst protocol, our most common form of treatment, which mimics natural brain rhythms and can finish a session in about 3 minutes. Regardless of length, you are awake and alert the entire time.</p></details><details class=\"faq\"><summary>Do I need someone to drive me home?</summary><p>No. You are awake and alert the entire time, and you can leave and drive yourself home immediately after your session ends.</p></details><details class=\"faq\"><summary>How many sessions will I need?</summary><p>A standard course is 36 sessions: 30 daily treatments over 6 weeks (Monday through Friday), followed by a 6-session taper. Your provider will explain the schedule for your plan.</p></details><details class=\"faq\"><summary>Does insurance cover TMS?</summary><p>Yes. NeuroStar TMS is covered by most major insurance companies, and more than 300 million people in the U.S. have insurance that covers it. Our team can help you find out if your plan covers it and assist with prior authorization. Financing options may be available for patients whose treatment is not covered by insurance.</p></details><details class=\"faq\"><summary>Is TMS safe? What are the side effects?</summary><p>The most common side effect is pain or discomfort at or near the treatment site. This is transient and does not occur for most patients after the first week of treatment. There is a rare risk of seizure associated with TMS therapy (less than 0.1% per patient).</p></details></div>\n<p class=\"note\" style=\"text-align:center;\">Information on this page is general and is not medical advice or a diagnosis. Call (254) 774-1163 with any questions.</p>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--navy)\"></span><span class=\"line\"></span></div>\n<section>\n<div class=\"section-inner\">\n<div class=\"section-head centered\"><span class=\"eyebrow\">Explore more</span><h2 style=\"color:var(--teal-deep)\">Other Services</h2></div>\n<div class=\"svc-grid\"><a class=\"svc-card\" href=\"/services/child-teen-psychiatry\" style=\"--accent:var(--purple)\"><h3>Child &amp; Teen Psychiatry</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/adult-psychiatry\" style=\"--accent:var(--sage)\"><h3>Adult Psychiatry</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/evaluations-medication-management\" style=\"--accent:var(--navy)\"><h3>Diagnosis &amp; Medication Management</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/surgical-employment-evaluations\" style=\"--accent:var(--yellow)\"><h3>Psychiatric Evaluations for Surgery, Employment &amp; More</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/psychological-testing\" style=\"--accent:var(--blue-light)\"><h3>Psychological Testing: ADHD, Autism, Learning Disabilities &amp; More</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/psychotherapy\" style=\"--accent:var(--yellow)\"><h3>Formal Therapy: Psychotherapy, Cognitive Behavioral Therapy &amp; More</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/counseling\" style=\"--accent:var(--sage)\"><h3>Informal Therapy: Counseling, Coaching, and Motivational Interviewing</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/child-therapy\" style=\"--accent:var(--purple)\"><h3>Child &amp; Teen Therapy</h3><span class=\"more\">Learn more →</span></a><a class=\"svc-card\" href=\"/services/esketamine\" style=\"--accent:var(--navy)\"><h3>Esketamine Nasal Spray</h3><span class=\"more\">Learn more →</span></a></div>\n<div class=\"cta-inline\" style=\"justify-content:center;\"><a class=\"btn btn-outline btn-navy\" href=\"/services\">View All Services</a></div>\n</div>\n</section>\n<div class=\"divider\"><span class=\"line\"></span><span class=\"dot\" style=\"background:var(--sage)\"></span><span class=\"line\"></span></div>\n<section class=\"refs\">\n<div class=\"section-inner\">\n<h3>Important Safety Information</h3>\n<p>The most common side effect is pain or discomfort at or near the treatment site. These events are transient; they occur during the TMS treatment course and do not occur for most patients after the first week of treatment. There is a rare risk of seizure associated with the use of TMS therapy (&lt;0.1% per patient).</p>\n<h3>Indications for Use</h3>\n<p>The NeuroStar Advanced Therapy System is indicated for the treatment of depressive episodes and for decreasing anxiety symptoms for those who may exhibit comorbid anxiety symptoms in adult patients suffering from Major Depressive Disorder (MDD) and who failed to achieve satisfactory improvement from previous antidepressant medication treatment in the current episode. NeuroStar Advanced Therapy is only available by prescription. A doctor can help decide if NeuroStar Advanced Therapy is right for you. Patients' results may vary. Visit neurostar.com for full safety and prescribing information.</p>\n<h3>References</h3>\n<ol>\n<li id=\"ref1\">World Health Organization, Depression Fact Sheet. Accessed April 8, 2024. https://www.who.int/news-room/fact-sheets/detail/depression.</li>\n<li id=\"ref2\">Post A, et al. (2001). <i>J Psychiatric Research</i>, 35:193-215.</li>\n<li id=\"ref3\">Liston C, Chen AC, Zebley BD, et al. (2014). <i>Biol Psychiatry</i>, 75(7):517-526.</li>\n<li id=\"ref4\">Data on file. Neuronetics, Inc. 2024.</li>\n<li id=\"ref5\">FDA Clearance K231926. The outcomes reported represent the subset of study patients for which CGI-S data was reported before and after an acute course of NeuroStar TMS. Patients aged 12 to 21 (average 19.2 ± 1.5) were treated under real-world conditions, where patients may have been prescribed concomitant depression treatments, including medications. “Measurable relief” was defined as a CGI-S score of 3 or lower, and “complete remission” was defined as a CGI-S score of 2 or lower, at the end of treatment.</li>\n<li>PET scans: Mark George, MD, Biological Psychiatry Branch, Division of Intramural Research Programs, NIMH 1993.</li>\n</ol>\n<p class=\"refs-note\">Information adapted from NeuroStar Advanced Therapy materials, ©2024 Neuronetics, Inc.</p>\n</div>\n</section>\n<section class=\"final-cta\">\n<h2>Ready to get started?</h2>\n<p>Book online in minutes, or call us at (254) 774-1163.</p>\n<a class=\"btn btn-solid btn-purple\" href=\"https://consumer.scheduling.athena.io?locationId=27185-1\">Book Now</a>\n</section>\n\n<script>\nfunction toggleMobileMenu() {\n  document.getElementById(\"mobileMenu\").classList.toggle(\"open\");\n  document.getElementById(\"navToggle\").classList.toggle(\"open\");\n}\n</script>\n";

export default function ServiceTmsPage() {
  return <main className="service-page service-page-tms" dangerouslySetInnerHTML={{ __html: content }} />;
}
